                                                                                          let currentRoom = -1;
                                                                                          if (rx >= -6 && rx < 2 && ry >= -6 && ry < 2) currentRoom = 0;
                                                                                          else if (rx >= -6 && rx < 2 && ry >= 2 && ry <= 6) currentRoom = 1;
                                                                                          else if (rx >= 2 && rx <= 6 && ry >= -2 && ry <= 6) currentRoom = 2;
